python3 -c "
import fitz, re
doc = fitz.open('docs/paper/main.pdf')

# Get detailed section headers using font size analysis
for i, page in enumerate(doc):
    blocks = page.get_text('dict')['blocks']
    print(f'=== PAGE {i+1} ===')
    for block in blocks:
        if 'lines' not in block:
            continue
        for line in block['lines']:
            text = ''.join(span['text'] for span in line['spans']).strip()
            if not text:
                continue
            sizes = [span['size'] for span in line['spans'] if span['text'].strip()]
            flags = [span['flags'] for span in line['spans'] if span['text'].strip()]
            if sizes:
                max_size = max(sizes)
                # Section headers tend to be larger or bold
                is_bold = any(f & 2**4 for f in flags)  # bit 4 = bold
                if max_size >= 11.5 and len(text) < 80:
                    print(f'  [sz={max_size:.1f} bold={is_bold}] {text}')
                elif max_size >= 10.5 and is_bold and len(text) < 80:
                    print(f'  [sz={max_size:.1f} bold={is_bold}] {text}')
    print()
" 2>&1
